import{a5 as l,ap as a,am as e,ax as d,cS as r,aw as c,av as o,m as h,bW as f,bY as v,bH as i}from"./index-BNgakYQ-.js";const u="https://visualizer.matthiasheckel.com/assets/video-vorschau-Dp8CC1tE.png",p="https://visualizer.matthiasheckel.com/assets/licht-BBwiHc7y.png",g="https://visualizer.matthiasheckel.com/assets/reflexion-vjycatPv.png",m="https://visualizer.matthiasheckel.com/assets/netzhaut-Dow86iFJ.png",b="https://visualizer.matthiasheckel.com/assets/gehirn-pEb_QzoB.png",k={},S={class:"lesson"},w={class:"lesson-nav","aria-label":"Kursnavigation"},E={class:"slide","aria-labelledby":"task-title"},N={class:"task-layout"},_={class:"drawing-grid",role:"img","aria-label":"Vorlage: vier leere Zeichenfelder in zwei Reihen"};function z(L,t){const s=v("router-link");return i(),a("main",S,[e("nav",w,[d(s,{to:{name:"3tgg12"}},{default:r(()=>[...t[0]||(t[0]=[c("← Zur Übersicht 3TGG12",-1)])]),_:1})]),t[5]||(t[5]=o('<section class="slide title-slide" aria-labelledby="lesson-title" data-v-f5c550d4><p class="eyebrow" data-v-f5c550d4>GRUNDLAGEN</p><h1 id="lesson-title" data-v-f5c550d4>VISUELLE<br data-v-f5c550d4>KOMMUNIKATION</h1><footer data-v-f5c550d4>CHS | Heckel</footer></section><section class="slide" aria-labelledby="video-title" data-v-f5c550d4><header class="subject" data-v-f5c550d4><span data-v-f5c550d4>GESTALTUNGS- UND MEDIENTECHNIK</span><span data-v-f5c550d4>Eingangsklasse</span></header><h2 id="video-title" class="section-title" data-v-f5c550d4>Sehen wir Farben alle gleich?</h2><a class="video-link" href="https://www.youtube.com/watch?v=UqLzSNaUelM" target="_blank" rel="noopener noreferrer" data-v-f5c550d4><img src="'+u+'" width="837" height="477" alt="Videovorschau: Dein Grün = mein Grün?" data-v-f5c550d4><span data-v-f5c550d4>▶ Video auf YouTube ansehen</span></a><footer data-v-f5c550d4>CHS | Heckel</footer></section><section class="slide" aria-labelledby="story-title" data-v-f5c550d4><header class="subject" data-v-f5c550d4><span data-v-f5c550d4>GESTALTUNGS- UND MEDIENTECHNIK</span><span data-v-f5c550d4>Eingangsklasse</span></header><h2 id="story-title" class="section-title" data-v-f5c550d4>Farbensehen beim Menschen</h2><p class="intro" data-v-f5c550d4>Vom Licht zum Farbeindruck – eine Bildergeschichte in vier Schritten.</p><ol class="story" data-v-f5c550d4><li data-v-f5c550d4><img src="'+p+'" width="386" height="387" alt="Eine Glühlampe sendet Lichtwellen aus." data-v-f5c550d4><h2 data-v-f5c550d4><span data-v-f5c550d4>1</span> Licht trifft auf einen Gegenstand</h2><p data-v-f5c550d4>Licht besteht aus elektromagnetischen Wellen. Sichtbares Licht umfasst verschiedene Wellenlängen. Weißes Licht enthält viele dieser Wellenlängen zusammen.</p></li><li data-v-f5c550d4><img src="'+g+'" width="382" height="387" alt="Licht trifft auf eine Oberfläche; ein Teil wird zurückgeworfen." data-v-f5c550d4><h2 data-v-f5c550d4><span data-v-f5c550d4>2</span> Die Oberfläche reflektiert Licht</h2><p data-v-f5c550d4>Ein Gegenstand nimmt einen Teil des Lichts auf (Absorption) und wirft einen anderen Teil zurück (Reflexion). Eine rote Fläche reflektiert bei weißer Beleuchtung vor allem langwelliges Licht.</p></li><li data-v-f5c550d4><img src="'+m+'" width="383" height="387" alt="Licht erreicht die Stäbchen und Zapfen auf der Netzhaut." data-v-f5c550d4><h2 data-v-f5c550d4><span data-v-f5c550d4>3</span> Die Netzhaut wandelt Licht in Signale um</h2><p data-v-f5c550d4>Das reflektierte Licht gelangt ins Auge und auf die Netzhaut. Dort reagieren Stäbchen besonders bei wenig Licht auf Helligkeit. Drei Zapfentypen reagieren unterschiedlich stark auf kurz-, mittel- und langwelliges Licht und ermöglichen das Farbensehen.</p></li><li data-v-f5c550d4><img src="'+b+'" width="386" height="387" alt="Eine Kopfzeichnung zeigt die Verbindung vom Auge zum Gehirn." data-v-f5c550d4><h2 data-v-f5c550d4><span data-v-f5c550d4>4</span> Im Gehirn entsteht der Farbeindruck</h2><p data-v-f5c550d4>Die Signale gelangen über den Sehnerv ins Gehirn. Es verarbeitet und vergleicht die Signale der Sinneszellen. So entsteht unser Farbeindruck – zum Beispiel Rot.</p></li></ol><footer data-v-f5c550d4>CHS | Heckel</footer></section>',3)),e("section",E,[t[2]||(t[2]=e("header",{class:"subject"},[e("span",null,"GESTALTUNGS- UND MEDIENTECHNIK"),e("span",null,"Eingangsklasse")],-1)),t[3]||(t[3]=e("h2",{id:"task-title",class:"section-title"},"Arbeitsauftrag",-1)),e("div",N,[t[1]||(t[1]=e("div",{class:"task-text"},[e("p",null,"Zeichnet vier Quadrate über eine Doppelseite in eurer Kladde."),e("p",null,"Stellt in vier zusammenhängenden Zeichnungen dar, wie der Sehvorgang beim Menschen funktioniert.")],-1)),e("div",_,[(i(),a(h,null,f(4,n=>e("div",{key:n})),64))])]),t[4]||(t[4]=e("footer",null,"CHS | Heckel",-1))])])}const D=l(k,[["render",z],["__scopeId","data-v-f5c550d4"]]);export{D as default};
